                        "Sex": item.Patient.Sex ? item.Patient.Sex : item.Patient.Gender,
                        "MobileNo": item.Patient.MobileNo,
                        "ContactNo": item.Patient.ContactNo,
                        "colors": value,
                        "PatientShortName": item.Patient.PatientName.substring(0, 2),
