                $scope.mainobj.RecievedForSurgeryNotes = resp.data.RecievedForSurgeryNotes || "";

                $scope.PatientAppointmentConsentForms = resp.data.PatientAppointmentConsentForms || [];
                $scope.OrganizationConsents = resp.data.OrganizationConsents || [];
                $scope.FilteredConsents = [];

                if (
                    $scope.OrganizationConsents.length > 0 &&
                    $scope.OrganizationConsents[0].ConsentTemplateDetails
                ) {
                    $scope.FilteredConsents = $filter('filter')(
                        $scope.OrganizationConsents[0].ConsentTemplateDetails,
                        { DocumentName: 'Instrucciones Anticipadas' },
                        true
                    );
                }
                $scope.PatientAppointmentConsentdata = [];
                if ($scope.PatientAppointmentConsentForms.length > 0) {
                    $scope.PatientAppointmentConsentdata = $scope.PatientAppointmentConsentForms;
                } else {
                    angular.forEach($scope.FilteredConsents, function (item) {
                        var obj = {};
                        obj.ConsentFormName = item.DocumentName;
                        obj.IsPatientSignRequired = item.IsPatientSignRequired;
                        obj.IsStaffSignRequired = item.IsStaffSignRequired;
                        obj.IsPatientSignatureDone = false;
                        obj.IsStaffSignatureDone = false;
                        obj.ConsentFormId = item.OrganisationConsentFormId;
                        $scope.PatientAppointmentConsentdata.push(obj);

                    });
                }
                $scope.selectedApptObj.ConsentNurseSignPending = '';
                $scope.selectedApptObj.ConsentDoctorSignPending = '';
                $scope.selectedApptObj.ConsentAnesthesiaSignPending = '';
