    /* ---------- LASIK signing status ----------
       A LASIK chart is stored as one row per phase - TypeId 1 Pre-Op, 2 Intra-Op,
       3 Post-Op - and reports its own three statuses instead of the Pre / Intra /
       Recovery ones the other charts use. The list reads them the same way the
       bulk sign-off screen does, so both screens agree on what is signed. */
    /* 3 is the LASIK chart, 4 the Laser (Yag, Retina) one - the popover on this
       screen names the phases from here, the same way UsASCBulkSignOffCtrl does. */
    /* the template this appointment opens, named for its category */
    $scope.GetLasikTemplateName = function () {
        return (Number(($scope.selectedApptObj || {}).SurgeryCategoryId) === 4)
            ? "Laser (Yag, Retina) Template"
            : "Lasik Template";
    };

    $scope.GetLasikWord = function (item) {
        return (Number((item || {}).LasikSurgeryCategoryId) === 4) ? "Laser" : "Lasik";
    };

    $scope.LasikSignOffPhases = [
        { "Key": "PreOp", "TypeId": 1, "TypeName": "Pre-Op", "Screen": "LasikPreop", "Status": "LasikPreopChartStatus", "SignOff": "LasikPreOpSignOffInfo" },
        { "Key": "IntraOp", "TypeId": 2, "TypeName": "Intra-Op", "Screen": "LasikIntraop", "Status": "LasikIntraopChartStatus", "SignOff": "LasikIntraOpSignOffInfo" },
        { "Key": "PostOp", "TypeId": 3, "TypeName": "Post-Op", "Screen": "LasikPostop", "Status": "LasikPostopChartStatus", "SignOff": "LasikPostOpSignOffInfo" }
    ];

    $scope.SeedLasikSignOffState = function (appointment) {
        if (!appointment) { return appointment; }

        appointment.SurgeryList = appointment.SurgeryList || [];
        appointment.LasikLastSignOffUserDetails = appointment.LasikLastSignOffUserDetails || [];

        /* This appointment's surgery category, taken from this appointment's own
           surgery.

           SurgeryList comes back holding every surgery in the response, not just
           this patient's - each row names the appointment it belongs to, so the
           rows are matched on that first. Reading SurgeryList[0] took whichever
           surgery happened to be first, which is why every patient came out as
           the same category. Kept identical to UsASCBulkSignOffCtrl. */
        var appointmentId = Number(appointment.AppointmentID || appointment.AppointmentId) || 0;
        var namesAnAppointment = false;
        var ownSurgeries = [];

        angular.forEach(appointment.SurgeryList, function (surgery) {
            var surgeryAppointmentId = Number((surgery || {}).AppointmentId || (surgery || {}).AppointmentID) || 0;

            if (surgeryAppointmentId !== 0) { namesAnAppointment = true; }
            if (surgeryAppointmentId !== 0 && surgeryAppointmentId === appointmentId) {
                ownSurgeries.push(surgery);
            }
        });

        if (!namesAnAppointment) { ownSurgeries = appointment.SurgeryList; }

        var surgeryCategoryId = 0;

        angular.forEach(ownSurgeries, function (surgery) {
            if (surgeryCategoryId === 0) {
                surgeryCategoryId = Number((surgery || {}).SurgeryCategoryId) || 0;
            }
        });

        /* SurgeryCategoryId 3 (LASIK) and 4 (Laser / YAG) are charted in the LASIK
           template. Every other category, and an appointment that states none, is
           charted in the Pre-Op / Intra-Op / Recovery notes as it always was. */
        appointment.IsLasikTemplate = (surgeryCategoryId === 3 || surgeryCategoryId === 4);
        /* the category the popover names its phases from - 3 LASIK, 4 LASER */
        appointment.LasikSurgeryCategoryId = surgeryCategoryId;
        /* The signing-status popover is compiled in its own scope and cannot reach
           the controller, but it is handed the appointment as popoverData - so the
           word it names the phases with travels on the appointment itself. */
        appointment.LasikWord = (surgeryCategoryId === 4) ? "Laser" : "LASIK";

        var signOffRows = appointment.LasikLastSignOffUserDetails;

        /* "Lasik-PreOp", "LasikPreop", "Pre-Op", "preop" all name the same phase,
           so names are compared with the punctuation and case taken out. */
        var normalize = function (value) {
            return String(value === undefined || value === null ? "" : value)
                .toLowerCase().replace(/[^a-z0-9]/g, "");
        };

        /* Read a field without caring how it is cased - this codebase spells
           TypeId, TypeID and DoctorID all three ways, and one wrong guess here
           reads undefined and drops the row. */
        var pick = function (row, fieldNames) {
            var wanted = fieldNames.map(normalize);
            var found;

            angular.forEach(row, function (value, key) {
                if (found !== undefined) { return; }
                if (wanted.indexOf(normalize(key)) !== -1 &&
                    value !== null && value !== undefined && value !== '') {
                    found = value;
                }
            });
            return found;
        };

        var rowBelongsToPhase = function (row, phase) {
            row = row || {};

            /* a numeric TypeId settles it outright */
            var rawTypeId = pick(row, ["TypeId", "LasikTypeId", "PhaseId"]);
            var typeId = Number(rawTypeId);
            if (rawTypeId !== undefined && !isNaN(typeId)) {
                return typeId === phase.TypeId;
            }

            /* no usable TypeId - fall back to whatever names the phase. A row that
               names nothing belongs to no phase, so it is never shown twice. */
            var names = [phase.Screen, phase.TypeName, phase.Key, "lasik" + phase.Key]
                .map(normalize);

            var candidate = normalize(pick(row, ["TypeName", "ScreenType", "Screen", "ScreenName", "TypeId"]));
            return candidate !== "" && names.indexOf(candidate) !== -1;
        };

        /* one shape for the popover, whatever the service called the fields */
        var toSignOffRow = function (row) {
            row = row || {};
            return {
                "SignOffUserName": pick(row, ["SignOffUserName", "UserFullName", "FullName", "SignOffUser", "SignedBy"]) || '',
                "SuffixName": pick(row, ["SuffixName", "Suffix"]) || '',
                "LicenseNumber": pick(row, ["LicenseNumber", "LicenseNo"]) || '',
                "Date": pick(row, ["Date", "SignOffDate", "SignedOffDate", "ReviewedByDateTime", "SignOffDateTime"]) || null
            };
        };

        var matchedRowCount = 0;

        angular.forEach($scope.LasikSignOffPhases, function (phase) {
            appointment[phase.Status] = appointment[phase.Status] || "";
            /* This line used to read:
                   if (appointment[phase.Status] !== "") { IsLasikTemplate = true; }
               It ran for every appointment, so any chart carrying a LASIK phase
               status had the flag forced on whatever its surgery category was -
               which is why it came out true for every patient. The category above
               decides it now; a status says one phase was signed, not which
               surgery was done. */

            appointment[phase.SignOff] = signOffRows.filter(function (row) {
                return rowBelongsToPhase(row, phase);
            }).map(toSignOffRow);

            matchedRowCount += appointment[phase.SignOff].length;
        });

        /* The service returns one sign-off list for the whole LASIK chart and its
           rows do not always name the phase they were signed from. When no row
           named a phase, read the list as it stands so a signed phase still shows
           its signer, date and time; rows repeated verbatim are collapsed so a
           column names each signer once. */
        if (signOffRows.length > 0 && matchedRowCount === 0) {
            var fallbackRows = [];
            var seenSigners = {};

            angular.forEach(signOffRows, function (row) {
                var signOff = toSignOffRow(row);
                var key = signOff.SignOffUserName + '|' + signOff.Date;

                if (seenSigners[key]) { return; }
                seenSigners[key] = true;
                fallbackRows.push(signOff);
            });

            angular.forEach($scope.LasikSignOffPhases, function (phase) {
                appointment[phase.SignOff] = angular.copy(fallbackRows);
            });
        }

        return appointment;
    };

    /* Active top level navigation module, "ASC" or "Laser".
       Owned by UsASCParentCtrl and inherited through the scope chain, so it survives every
       filter/search/refresh inside this screen. Never assign to it from here. */
    function getASCModuleType() {
        return ($scope.ParentObj && $scope.ParentObj.ASCModuleType) || "ASC";
    }

    /* Single source of truth for the "SurgeryCategoryIds" request parameter of
       GetAllAscAppointmentsList, GetASCDynamicStatusForAppointmentList and
       GetASCDynamicStatusListByType.
       The top level navigation module is the only thing that decides it, no filter, search,
       date change or room tab may alter it. So ASC List never sends category 4 and Laser
       never sends anything but category 4. */
    $scope.GetASCListSurgeryCategoryIds = function () {
        return $scope.ASCModuleSurgeryCategoryIds[getASCModuleType()] || $scope.ASCModuleSurgeryCategoryIds.ASC;
    };

    function getASCModuleAppointmentTypeId() {
        return getASCModuleType() === "Laser" ? "14" : "4";
    }

    function GetModuleVisitReasons(rows) {

        let visitTypeId = getASCModuleType() === "Laser" ? 14 : 4;

        return $filter('filter')(
            rows || [],
            { 'VisitTypeId': visitTypeId },
            true
        );
    }

    /* Reloads the list exactly the way every other ASC refresh path does, keeping the
       currently selected reception/room sub tab. */
    function RefreshASCListForCurrentModule() {
        if ($scope.ASCDynamicStatusTabs.Subtab === 2) {
            $scope.SearchSurgeryList(1);
        } else if ($scope.ASCDynamicStatusTabs.Subtab === 3) {
            $scope.SearchSurgeryList(2);
        } else if ($scope.ASCDynamicStatusTabs.Subtab === 4) {
            $scope.SearchSurgeryList(3);
        } else if ($scope.ASCDynamicStatusTabs.Subtab > 4) {
            /* Room sub tab. GetApptListByRoomType does not refresh the count cards itself. */
            $scope.GetASCDynamicStatusCounts();
            $scope.GetApptListByRoomType($scope.RoomTypeId, $scope.ASCDynamicStatusTabs.Subtab);
        } else {
            $scope.SearchSurgeryList(0, 'tab');
        }
    }


    function LoadASCModuleVisitReasons() {

        var visitTypeId = getASCModuleType() === "Laser" ? 14 : 4;

        if ($scope.mainAscParentObj.IsAscBranchAvailable && $scope.AppListdoctoraddress.length > 0) {
            var TempAppListdoctoraddress = $filter("filter")($scope.AppListdoctoraddress, function (iterator, ind) { return iterator.ClinicId !== 0; });
            var Org_id = _.pluck(TempAppListdoctoraddress, "ClinicId").join(",");
        } else {
            var Org_id = $scope.HospitalId;
        }

        var obj = {
            "OrganizationId": Org_id || 0,
            "UserId": doctorinfo.doctorid,
            "VisitTypeId": 0,
            "visitReasonSearch": "",
            "PageNumber": 1,
            "PageSize": 1000,
            "IsFrequent": "N"
        };

        return eHnotePatientVisitReasonServices.GetOrganizationActiveAndInActiveApptVisitReasons(obj).then(function (resp) {

            if (resp.data !== undefined && resp.data.rows) {

                // Keep all active reasons for calendar if required
                $scope.CalVisitreasons = $filter("filter")(
                    resp.data.rows,
                    function (item) {
                        return item.ActiveInd == "Y";
                    }
                );

                // IMPORTANT:
                // ASC -> VisitTypeId 4
                // Laser -> VisitTypeId 14

                $scope.Visitreasons = $filter('filter')(
                    resp.data.rows,
                    { 'VisitTypeId': visitTypeId },
                    true
                );

                // New module should start with all its reasons selected
                angular.forEach($scope.Visitreasons, function (item) {
                    item.isChecked = true;
                });

                $scope.selectedVisitReason = 'All Visit Reasons';
                $scope.AllDoctorsObj.AllVisitReasonsCheck = true;
            }
        });
    }




    /* Switching between the "ASC List" and "Laser" top navigation items keeps Tab == 'asclist',
       so this controller is not re-created and has to reload itself. Coming from any other
       module the controller is created fresh and simply reads ParentObj.ASCModuleType. */
    $scope.$on('ASCModuleTypeChanged', function (event, data) {
        if (!data || (data.ASCModuleType !== "ASC" && data.ASCModuleType !== "Laser")) {
            return;
        }

        /* Drop anything still in flight for the module we are leaving. */
        $scope.ASCModuleRequestToken++;

        /* The previously selected appointment belongs to the other category group. */
        $scope.AscAppointmentsList = [];
        $scope.MainAscAppointmentsList = [];
        $scope.NavObj.IsApptSelectedInfoInd = false;
        $scope.selectedApptObj = "";
        $scope.cacheStorageItem.AppointmentId = 0;
        $scope.SurgeryListPageNo = 1;

        // FIRST load Visit Reasons for the newly selected module
        LoadASCModuleVisitReasons().then(function () {

            // THEN load appointment list
            RefreshASCListForCurrentModule();

        });
    });

