                        angular.forEach($scope.selectedAsclist.PatientTagList, function (Selecteditem) {
                            angular.forEach($scope.PatientTagList, function (Mainitem) {
                                if (Selecteditem.HospitalEquipmentId == Mainitem.HospitalEquipmentId) {
                                    Mainitem.IsChecked = true;
                                }
                            });
                        });
                        var checkedArray = _.where($scope.PatientTagList, { IsChecked: true });
                        $scope.TagPatientObj.AllPatientTagsCheck = checkedArray.length > 0 && $scope.PatientTagList.length === checkedArray.length ? true : false;
                        if ($scope.TagPatientObj.AllPatientTagsCheck) {
                            $scope.TagPatientObj.SelectTag = 'All';
                        }

                        if (!$scope.TagPatientObj.AllPatientTagsCheck && checkedArray.length > 0) {
                            $scope.TagPatientObj.SelectTag = 'Selected';
                        } else if (checkedArray.length == 0) {
                            $scope.TagPatientObj.SelectTag = 'Select Tag Patient';
                        }
