    $scope.clickcheckin = function (item) {

        //if ($scope.selectedApptObj.CheckinStatusId === 1 || $scope.selectedApptObj.CheckinStatusId === null) {
        //    alertify.error("Patient has not checkedin yet!");
        //    return;
        //}
        if ($scope.UserAccessRights.AllAccessRights.AdmitAccess == false) {
            alertify.error("No access for this user.");
            return false;
        }


        //if ($scope.selectedApptObj.AppointmentStatusId === 1) {
        //    alertify.error("Patient has not checkedin yet!");
        //    return;
        //}

        if ($scope.selectedApptObj.AppointmentStatusId === 7 || $scope.selectedApptObj.AppointmentStatusId === 5 || $scope.selectedApptObj.AppointmentStatusId === 6) {
            alertify.error("Appointment Cancelled!");
            return;
        }

        if ($scope.selectedApptObj.AppointmentStatusId === 8 || $scope.selectedApptObj.AppointmentStatusId === 9 || $scope.selectedApptObj.AppointmentStatusId === 10) {
            alertify.error("Appointment Rescheduled!");
            return;
        }



        let params = {
            "AppointmentId": $scope.selectedApptObj.AppointmentID || 0,
        };

        eHnoteMainAppointmentService.GetLatestTrackerStatusById(params).then(function (resp) {
            if (resp.data.Status === "Success") {
                if (resp.data.rows.length > 0) {
                    let DynamicStatusObj = resp.data.rows[0];
                    if (DynamicStatusObj.RoomTypeId !== 11) {
                        alertify.confirm(
                            "<b class='txt-centre'>Confirm!</b><h4 class='txt-body-centre pl-20 pr-20'>The patient is at OP " + DynamicStatusObj.RoomType + " , would you like to first tranfer patient to ASC Reception before admitting? </h4>",
                            function () {

                                $scope.PatientTagList = [];
                                $scope.PatientTagList = angular.copy($scope.mainobj.Patientlist[0].PatientTagList);

                                let CurrentTime = $filter("date")(new Date(), "HH:mm:ss");
                                let params = {
                                    "UserId": eHnoteMasterDataService.getLoginId(),
                                    "TransferUserId": eHnoteMasterDataService.getLoginId(),
                                    "HospitalId": $scope.HospitalId,
                                    "AppointmentId": $scope.selectedApptObj.AppointmentID,
                                    "AppointmentTrackerDetailId": 0,
                                    "RoleId": $scope.RoleId,
                                    "VisitReason": $scope.selectedApptObj.VisitReason || "",
                                    "AttenderName": "",
                                    "DoctorId": null,
                                    "DoctorRoleId": null,
                                    "RoomTypeId": DynamicStatusObj.RoomTypeId || null,
                                    "RoomId": null,
                                    "Remarks": "ASC transfer",
                                    "CurrentTime": CurrentTime,
                                    "IsSendTo": "N",
                                    "IsCheckedIn": "N",
                                    "IsCheckedOut": "N",
                                    "IsReCheckIn": "N",
                                    "IsReCheckOut": "N",
                                    "IsExpressCheckedOut": "N",
                                    "VisitTypeId": $scope.selectedApptObj.VisitTypeId || null,
                                    "HospitalEquipmentId": $scope.selectedApptObj.HospitalEquipmentId || null,
                                    "PatientTagList": $scope.PatientTagList
                                }
                                eHnoteMainAppointmentService.AddUpdateAppointmentTrackerDetails(params).then(function (resp) {
                                    console.log(resp);
                                    if (resp.data.Status == "Success") {
                                        let CurrentTime = $filter("date")(new Date(), "HH:mm:ss");
                                        let params = {
                                            "UserId": eHnoteMasterDataService.getLoginId(),
                                            "TransferUserId": eHnoteMasterDataService.getLoginId(),
                                            "HospitalId": $scope.HospitalId,
                                            "AppointmentId": $scope.selectedApptObj.AppointmentID,
                                            "AppointmentTrackerDetailId": 0,
                                            "RoleId": $scope.RoleId,
                                            "VisitReason": $scope.selectedApptObj.VisitReason || "",
                                            "AttenderName": "",
                                            "DoctorId": null,
                                            "DoctorRoleId": null,
                                            "RoomTypeId": 11,
                                            "RoomId": null,
                                            "Remarks": "ASC transfer",
                                            "CurrentTime": CurrentTime,
                                            "IsSendTo": "Y",
                                            "IsCheckedIn": "N",
                                            "IsCheckedOut": "N",
                                            "IsReCheckIn": "N",
                                            "IsReCheckOut": "N",
                                            "IsExpressCheckedOut": "N",
                                            "VisitTypeId": $scope.selectedApptObj.VisitTypeId || null,
                                            "HospitalEquipmentId": $scope.selectedApptObj.HospitalEquipmentId || null,
                                            "PatientTagList": $scope.PatientTagList
                                        }
                                        eHnoteMainAppointmentService.AddUpdateAppointmentTrackerDetails(params).then(function (response) {
                                            if (response.data.Status == "Success") {
                                                alertify.success('Patient successfully transferred to ASC Reception!');

                                                item = item || '';
                                                // $location.url("/AscModule");
                                                $scope.OpenAdmitPopup();
                                            }

                                        }, function () {
                                            alertify.error("Getting Failed");
                                        });
                                    }
                                });
                            }, function () {

                            });
                    } else {

                        item = item || '';
                        //$location.url("/AscModule");
                        $scope.OpenAdmitPopup();
                    }
                } else {
                    $scope.OpenAdmitPopup();
                }
            }

        }, function () {

        });


    }
