    $scope.GetApptListByRoomType = function (val, subtab) {
        $scope.Autoclick = true;
        val = val || 0;
        $scope.RoomTypeId = val;
        $scope.ASCDynamicStatusTabs.Subtab = subtab;

        if ($scope.AppointmentStatusArray.length > 0) {
            angular.forEach($scope.AppointmentStatusArray, function (kitem) {
                kitem.IsChecked = true;
                if (kitem.AppointmentStatusId === 5 || kitem.AppointmentStatusId === 8 || kitem.AppointmentStatusId === 9 || kitem.AppointmentStatusId === 10) {
                    kitem.IsChecked = false;
                }
            });
        }

        var checkedArrayList = [];
        if ($scope.MultiselectDoctorlist.length > 0) {
            checkedArrayList = _.where($scope.MultiselectDoctorlist, { isChecked: true });
        }
        var checkedVisitreasons = [];
        if ($scope.Visitreasons.length > 0) {
            checkedVisitreasons = _.where($scope.Visitreasons, { isChecked: true });
        }
        var checkedBookingTypesArray = [];
        if ($scope.BookingTypesArray.length > 0) {
            checkedBookingTypesArray = _.where($scope.BookingTypesArray, { IsChecked: true });
        }
        var checkedAppointmentStatusArray = [];
        if ($scope.AppointmentStatusArray.length > 0) {
            checkedAppointmentStatusArray = _.where($scope.AppointmentStatusArray, { IsChecked: true });
        }
        var checkedBookedstatusFilterList = [];
        if ($scope.BookedstatusFilterList.length > 0) {
            checkedBookedstatusFilterList = _.where($scope.BookedstatusFilterList, { IsChecked: true });
        }
        var checkedProfileStatusList = [];
        if ($scope.ProfileStatusList.length > 0) {
            checkedProfileStatusList = _.where($scope.ProfileStatusList, { IsChecked: true });
        }
        var checkedPatientTagList = [];
        if ($scope.PatientTagList.length > 0) {
            checkedPatientTagList = _.where($scope.PatientTagList, { IsChecked: true });
        }
        var checkedAppointmentStatusFilterArray = [];
        if ($scope.AppointmentStatusFilterArray.length > 0) {
            checkedAppointmentStatusFilterArray = _.where($scope.AppointmentStatusFilterArray, { isChecked: true });
        }
        var cacheobj = {
            "SelectedDoctorsList": checkedArrayList || [],
            "OPFromDate": $scope.SearchObj.ConsultationDt || "",
            "PatientTagList": checkedPatientTagList || [],
            "ProfileStatusList": checkedProfileStatusList || [],
            "BookedstatusFilterList": checkedBookedstatusFilterList || [],
            "AppointmentStatusArray": checkedAppointmentStatusArray || [],
            "BookingTypesArray": checkedBookingTypesArray || [],
            "Visitreasons": checkedVisitreasons || [],
            "AppointmentStatusFilterArray": checkedAppointmentStatusFilterArray || [],
            "Subtab": $scope.ASCDynamicStatusTabs.Subtab || 0,
            "RoomTypeId": $scope.RoomTypeId || 0,
        };
        eHnoteMasterDataService.addSelectedAscList(cacheobj);
        let newlist1 = "";
        for (var i in $scope.AppointmentStatusFilterArray) {
            if ($scope.AppointmentStatusFilterArray[i].isChecked) {
                newlist1 += "," + $scope.AppointmentStatusFilterArray[i].Id;
            }
        }
        if (newlist1.charAt(0) === ",") {
            newlist1 = newlist1.slice(1);
        }

        let newlist2 = "";
        for (var i in $scope.Visitreasons) {
            if ($scope.Visitreasons[i].isChecked) {
                newlist2 += "," + $scope.Visitreasons[i].ReasonId;
            }
        }
        if (newlist2.charAt(0) === ",") {
            newlist2 = newlist2.slice(1);
        }

        let newlist3 = "";
        for (var i in $scope.BookingTypesArray) {
            if ($scope.BookingTypesArray[i].IsChecked) {
                newlist3 += "," + $scope.BookingTypesArray[i].BookingTypeId;
            }
        }
        if (newlist3.charAt(0) === ",") {
            newlist3 = newlist3.slice(1);
        }

        let newlist4 = "";
        for (var i in $scope.AppointmentStatusArray) {
            if ($scope.AppointmentStatusArray[i].IsChecked) {
                newlist4 += "," + $scope.AppointmentStatusArray[i].AppointmentStatusId;
            }
        }
        if (newlist4.charAt(0) === ",") {
            newlist4 = newlist4.slice(1);
        }

        let newlist5 = "";
        for (var i in $scope.BookedstatusFilterList) {
            if ($scope.BookedstatusFilterList[i].IsChecked) {
                newlist5 += "," + $scope.BookedstatusFilterList[i].Id;
            }
        }
        if (newlist5.charAt(0) === ",") {
            newlist5 = newlist5.slice(1);
        }

        let newlist6 = "";
        for (var i in $scope.ProfileStatusList) {
            if ($scope.ProfileStatusList[i].IsChecked) {
                newlist6 += "," + $scope.ProfileStatusList[i].Id;
            }
        }
        if (newlist6.charAt(0) === ",") {
            newlist6 = newlist6.slice(1);
        }

        let newlist7 = "";
        for (var i in $scope.PatientTagList) {
            if ($scope.PatientTagList[i].IsChecked) {
                newlist7 += "," + $scope.PatientTagList[i].HospitalEquipmentId;
            }
        }
        if (newlist7.charAt(0) === ",") {
            newlist7 = newlist7.slice(1);
        }

        let newlist8 = "";
        for (var i in $scope.MultiselectDoctorlist) {
            if ($scope.MultiselectDoctorlist[i].isChecked) {
                newlist8 += "," + $scope.MultiselectDoctorlist[i].DoctorID;
            }
        }
        if (newlist8.charAt(0) === ",") {
            newlist8 = newlist8.slice(1);
        }
        var Locationids = '';
        if ($scope.GetAllIndicatorForFacility == 1 || $scope.AppListselectedclinic.ClinicId === 0) {
            var TempAppListdoctoraddress = $filter("filter")($scope.AppListdoctoraddress, function (iterator, ind) { return iterator.ClinicId !== 0; });
            Locationids = _.pluck(TempAppListdoctoraddress, "ClinicId").join(",");
        } else {
            Locationids = $scope.AppListselectedclinic.ClinicId;
        }
        let consultationDt = $filter('date')($scope.SearchObj.ConsultationDt, "yyyy-MM-dd");

        let surgeryCategoryIds = $scope.GetASCListSurgeryCategoryIds();
        let requestToken = $scope.ASCModuleRequestToken;
        let appointmentTypeStatusId = getASCModuleAppointmentTypeId();

        let params = {
            "DoctorIds": newlist8,
            "ConsultationDt": consultationDt,
            "HospitalID": $scope.HospitalId,
            "PageSize": 600,
            "PageNumber": 1,
            "UserId": $scope.UserId,
            "AppointmentTypeStatusIDList": appointmentTypeStatusId,
            "VisitReasonIdList": newlist2,
            "BookingTypeIds": newlist3,
            "AppointmentStatusIds": newlist4,
            "BookingStatusIds": newlist5,
            "ProfileStatusIds": newlist6,
            "PatientTagListIds": newlist7,
            "RoomTypeId": $scope.RoomTypeId,
            "Locationids": Locationids,
            "SurgeryCategoryIds": surgeryCategoryIds,
        }

        eHnotePatientDataService.GetASCDynamicStatusListByType(params).then(function (resp) {
            /* Response of a top level module the user already left, ignore it. */
            if (requestToken !== $scope.ASCModuleRequestToken) {
                return;
            }
            if (resp.data.status == "Success") {
                $scope.mainobj = {
                    "AppointmentId": '',
                    "PatientId": '',
                    "Patientlist": [],

                }
                $scope.AscAppointmentsList = resp.data.rows;
                $scope.AscAppointmentsListCount = resp.data.Count;
                const diabetesIds = [640, 641, 804, 808, 926, 927, 966, 587, 874, 953, 697, 696];
                if ($scope.AscAppointmentsList.length > 0) {

                    angular.forEach($scope.AscAppointmentsList, function (item) {
                        if ($scope.ASCDynamicStatusTabs.Subtab == 8) {
                            item.DischargeSignOffStartTime = item.DischargeSignOffStartTime || '';
                            item.DischargeSignOffEndTime = item.DischargeSignOffEndTime || '';
                            item.DischargeTime = item.DischargeTime || '';
                            item.IsForceEarlySignedOff = item.IsForceEarlySignedOff || false;

                            item.IsTimerStoped = item.IsTimerStoped || false;

                            //if (item.DischargeSignOffStartTime !== '' && item.DischargeSignOffEndTime == '') {
                            //    $scope.ShowTimer(item, item.DischargeTime);
                            //} else {
                            //    if (item.DischargeSignOffEndTime !== '') {
                            //        item.DischargeTimerStartTime = item.DischargeSignOffEndTime;
                            //    } else {
                            //        item.DischargeTimerStartTime = '';
                            //    }

                            //}
                            item.DischargeTimerStartTime = item.DischargeTimerStartTime || '';

                            if (item.DischargeTime !== '') {
                                if (item.IsForceEarlySignedOff) {
                                    item.DischargeTimerStartTime = item.DischargeSignOffEndTime;
                                    item.IsTimerStoped = true;
                                } else if (item.DischargeSignOffStartTime !== '') {
                                    const now = new Date();
                                    const timeStr = item.DischargeSignOffStartTime;
                                    if (timeStr && typeof timeStr === 'string' && timeStr.includes(":")) {
                                        const time24 = convertTo24Hour(timeStr);
                                        const parsedStartTime = new Date(`1970-01-01T${time24}:00`);
                                        const startTime = new Date(now);
                                        startTime.setHours(parsedStartTime.getHours(), parsedStartTime.getMinutes(), 0, 0);
                                        if (startTime > now) {
                                            startTime.setDate(startTime.getDate() - 1);
                                        }
                                        const diffMs = now - startTime;
                                        const totalMinutes = Math.floor(diffMs / (1000 * 60));
                                        var timeDifferenceInMinutes = totalMinutes;

                                        var DischargeTime = parseFloat(item.DischargeTime);

                                        if (timeDifferenceInMinutes >= DischargeTime) {
                                            item.DischargeTimerStartTime = item.DischargeSignOffEndTime;
                                            item.IsTimerStoped = true;
                                        } else {
                                            $scope.ShowTimer(item, item.DischargeTime);
                                        }
                                    }
                                }
                            } else {
                                if (item.DischargeSignOffStartTime !== "" && item.DischargeSignOffEndTime !== "") {
                                    item.IsTimerStoped = true;
                                }
                            }
                        }
                        var ConvertWalkInTime = $filter('date')(item.WalkInTime, "hh:mm a") || "";
                        item.CheckInTime = "";
                        item.CheckInTime = ConvertWalkInTime;
                        var datetime = item.ConsultationDt + "T" + item.StartTime;
                        item.ConvertDateStartTime = $filter('date')(datetime, "hh:mm a");
                        item.ConsultationDate = $filter('date')(item.ConsultationDt, "MM-dd-yyyy");
                        item.IsDoctorDoctroNotesSignOff = item.FaceSheetLastSignOffUserDetails.some(ditem => ditem.UserType != "Nurse");
                        item.IsDoctorOperativeNotesSignOff = item.OperativeLastSignOffUserDetails.some(ditem => ditem.UserType != "Nurse");
                        item.IsDoctorDisChargeSignOff = item.DischargeLastSignOffUserDetails.some(ditem => ditem.UserType != "Nurse");
                        // for past date validations
                        let today = $filter('date')(new Date(), "yyyy-MM-dd");
                        today = today + " " + "00:00:00";
                        today = new Date(today);
                        let date1 = item.ConsultationDt;
                        date1 = date1 + " " + "00:00:00";
                        date1 = new Date(date1);
                        let t1 = today.getTime();
                        let t2 = date1.getTime();

                        if (t1 > t2) {
                            item.IsPastAppointment = true;
                            item.IsFutureAppointment = false;
                            item.IsCurrentAppointment = false;
                        } else if (t1 < t2) {
                            item.IsPastAppointment = false;
                            item.IsFutureAppointment = true;
                            item.IsCurrentAppointment = false;
                        } else if (t1 == t2) {
                            item.IsPastAppointment = false;
                            item.IsFutureAppointment = false;
                            item.IsCurrentAppointment = true;
                        }
                        if (item.Patient.MobileNo.length > 0) {
                            var obj = eHnoteUserDataService.UsMobileFormatChange(item.Patient.MobileNo);
                            item.Patient.MobileNo = obj.UsFormatMobileNumber;
                        }
                        item.CurrentloginuserRoleId = $scope.RoleId || 0;
                        /* a LASIK chart reports its own three phase statuses and its own signers */
                        $scope.SeedLasikSignOffState(item);

                        item.SystemicHistory = item.SystemicHistory || [];
                        if (!$scope.ParentObj.IsIOJParentOrganization && item.SystemicHistory.length > 0) {
                            let diabetesSet = [];
                            angular.forEach(item.SystemicHistory, function (ssitem) {
                                if (diabetesIds.includes(ssitem.HistoryId)) {
                                    item.hasDiabetes = true;
                                    diabetesSet.push(ssitem.HistoryName);
                                }
                            });
                            item.diabetesString = [...new Set(diabetesSet)].join(',') || '';
                        }


                    });
                    var val = $scope.cacheStorageItem.AppointmentId || "";
                    if ($scope.AscAppointmentsList.length > 0 && val != "") {
                        let ApptInfo = $filter('filter')($scope.AscAppointmentsList, { 'AppointmentID': val }, true)[0] || 0;
                        var indexofAppt = $scope.AscAppointmentsList.indexOf(ApptInfo) || 0;
                        if (indexofAppt > -1) {
                            $scope.SelectAppointment1($scope.AscAppointmentsList[indexofAppt]);
                        } else {
                            $scope.NavObj.IsApptSelectedInfoInd = false;
                        }
                    }
                    //    $scope.SelectAppointment1($scope.AscAppointmentsList[0]);
                } else {
                    $scope.NavObj.IsApptSelectedInfoInd = false;
                }
            }

        });

        $scope.GetASCDynamicStatusCounts();
    };



