    $scope.EditASCAppointmentPopup = function (item, opentype) {
        var opentype = opentype || 1;
        if ($scope.UserAccessRights.AllAccessRights.AscRescheduleAppt == false) {
            alertify.error("No access for this user.");
            return false;
        }
        var Sarray = item.StartTime.split(":");
        var stime = Sarray[0] + ":" + Sarray[1];
        var date = moment(item.ConsultationDt).format();
        var earray = item.EndTime.split(":");
        var etime = earray[0] + ":" + earray[1];
        var apptime = item.AppointmentID;
        var VisitTypeId = item.VisitTypeId || "";
        VisitTypeId = VisitTypeId != '' ? VisitTypeId : 0;
        var VisitRemarks = item.VisitRemarks || "";

        $scope.AppDate = [stime, etime, apptime, item.VisitReason ? item.VisitReason : "", item.ReferralSourceId ? item.ReferralSourceId : "", VisitTypeId, VisitRemarks];

        $scope.calenderDate = moment(date).format("DD-MMM-YYYY" + " " + stime);

        $scope.PageName = "reschedule";

        let surgeryList = [];
        if (item.AppointmentTypeId == 7) {
            surgeryList = angular.copy(item.PreAdmSurgeryList);

        } else if (item.AppointmentTypeId == 4 || item.AppointmentTypeId == 14) {
            surgeryList = angular.copy(item.SurgeryList);
        }

        var Obj = {
            "PageName": "reschedule",
            "AppDate": $scope.AppDate,
            "ispatientExistsval": true,
            "calenderDate": $scope.calenderDate,
            "AppointmentDate": item.ConsultationDt,
            "AppointmentId": item.AppointmentID || null,
            "PatientId": item.PatientID || null,
            'IsComingFrom': '',
            "DoctorId": item.DoctorID,
            "StartTime": stime || "",
            "EndTime": etime,
            'type': 'op',
            "SurgeryList": surgeryList || [],
            "BranchId": item.BranchId || 0,
        };
        datapersistanceFactory.set('AppointmentDetailsCache', Obj);
        let LogItem = {
            "SubModuleId": 2,
            "SubModuleName": "Reschedule",
            "ScreenType": "ASC List",
            "ActionType": "Accessed",
            "ActionDescription": `Reschedule Appointment Screen from ASC List For Appointment ID : ${$scope.LogObj.AppointmentId}`,
        }
        $scope.AddAuditLog(LogItem);
        if (opentype == 2) {
            BookApptPopupOpenedv2();
        } else {
            BookApptPopupOpened();
        }

    };
