    function browserInfo() {
        const ua = navigator.userAgent;

        if (ua.indexOf("Chrome") > -1 && ua.indexOf("Edg") === -1 && ua.indexOf("OPR") === -1) {
            return "Chrome";
        } else if (ua.indexOf("Safari") > -1 && ua.indexOf("Chrome") === -1) {
            return "Safari";
        } else if (ua.indexOf("Firefox") > -1) {
            return "Firefox";
        } else if (ua.indexOf("Edg") > -1) {
            return "Edge";
        } else if (ua.indexOf("OPR") > -1 || ua.indexOf("Opera") > -1) {
            return "Opera";
        } else {
            return "Unknown";
        }
    }
    $scope.$watch("SearchObj.ConsultationDt", function (newVal, oldVal) {

        // The uib-datepicker is bound to CalendarPickerDate (a real Date object), not
        // SearchObj.ConsultationDt directly — that string is relied on elsewhere for API params, but
        // the datepicker's own render() does a bare `new Date(ngModelCtrl.$viewValue)` on whatever
        // its model holds, and "MM-DD-YYYY" isn't ISO 8601/RFC 2822, so it parses inconsistently
        // across browsers/timezones. Keep a Date-typed mirror in sync here instead.
        $scope.CalendarPickerDate = safeNewDate(newVal);


        let broswerName = browserInfo();
        if (broswerName === "Safari") {
            $scope.showifnotCurrentDate = true;
            $scope.currentDate = new Date();
            if (moment(newVal, 'MM-DD-YYYY').isValid()) {
                $scope.selectedDate = moment(newVal, "MM-DD-YYYY").format("YYYY-MM-DD");
                console.log($scope.currentDate + "__" + $scope.selectedDate);
                var refDate = moment().format('YYYY-MM-DD');
                if (moment(refDate).isSame($scope.selectedDate)) {
                    console.log("The target date is equal to the current date");
                    $scope.showifnotCurrentDate = false;
                }
                $scope.SearchObj.ConsultationDt = $scope.selectedDate;
            } else {
                console.log("Invalid date format: " + newVal);
                var TodayDate = moment().format('YYYY-MM-DD');  // today date
                var refDate = $filter('date')(newVal, "yyyy-MM-dd");
                if (moment(refDate).isSame(TodayDate)) {
                    console.log("The target date is equal to the current date");
                    $scope.showifnotCurrentDate = false;
                }
                // Handle invalid date format here if necessary
                var TodayDate = moment().format('YYYY-MM-DD');  // today date
                var refDate = $filter('date')(newVal, "yyyy-MM-dd");
                if (moment(refDate).isSame(TodayDate)) {
                    console.log("The target date is equal to the current date");
                    $scope.showifnotCurrentDate = false;
                }
            }
        } else {
            $scope.showifnotCurrentDate = true;
            $scope.currentDate = new Date();
            $scope.selectedDate = moment(newVal).format('MM-DD-YYYY');
            console.log($scope.currentDate + "__" + $scope.selectedDate);
            var refDate = $filter('date')(new Date(), "MM-dd-yyyy");
            if (moment(refDate).isSame($scope.selectedDate)) {
                console.log("The target date is equal to the current date");
                $scope.showifnotCurrentDate = false;
            }
        }
    }, true);

