    $scope.onClickCheckInPopup = function (item, ind) {
        if (item.BookingTypeId == 2) {
            alertify.error("Patient is in waiting status! Please make sure patient has confirmed appointment. ");
            return false;
        }

        if ($scope.queueSettingObj.IsEnabled) {
            var DiffMinutes = getcurrentTimeDifferenceMinutesNew(item.StartTime);

            if (DiffMinutes > 0) {
                if (DiffMinutes > $scope.queueSettingObj.CheckInAvgTime) {
                    alertify.error("You cannot Check IN before appointment time");
                    return false;
                }
            }
        }

        let ConsultationDt = item.ConsultationDt || '';
        if (ConsultationDt != '') {
            $scope.IsFutureAppointmentDate = eHnotePatientDataService.IsFutureDate(item.ConsultationDt);
        }

        if ($scope.IsFutureAppointmentDate) {
            alertify.error("for future appointment Checkin/Checkout not allowed");
            return;
        }

        $scope.checkInObj.AppointmentId = item.AppointmentID;
        $scope.checkInObj.VisitReason = item.VisitReason;
        $scope.checkInObj.AttenderName = item.AttenderName;

        $scope.ApptObj.HospitalEquipmentId = item.HospitalEquipmentId || "";
        $scope.ApptObj.VisitTypeId = item.VisitTypeId || 0;
        $scope.ApptObj.AppointmentTypeId = item.AppointmentTypeId || 0;
        $scope.ApptObj.VisitReasonName = item.VisitReason || '';
        $scope.ApptObj.AppointmentStatusId = item.AppointmentStatusId || null;
        $scope.ApptObj.BookingStatusId = item.BookingStatusId || null;

        $scope.Technishionsend(item, "NotCheckIN");

    };

    $scope.OpenCheckoutRollBack = function (item) {

        if (item.ProfileStatus === "Completed") {
            if ($scope.AscAppointmentsList.length > 0) {
                let row = $filter('filter')($scope.AscAppointmentsList,
                    { 'AppointmentID': item.AppointmentID }, true)[0];

                if (row) {
                    let index = $scope.AscAppointmentsList.indexOf(row);
                    $scope.CheckoutRollBack(row, index);
                } else {
                    // No matching appointment found — handle accordingly
                    $scope.CheckoutRollBack();
                }
            } else {
                $scope.CheckoutRollBack();
            }
            return; // Early return — profile is Completed
        }
        var resolveobj = {
            "PatientID": item.PatientID,
            "AppointmentID": item.AppointmentID,
            "BranchId": item.BranchId,
            "ConsultationDt": item.ConsultationDt,
            "DoctorID": item.DoctorID,
            "AppointmentStatusId": item.AppointmentStatusId,
            "AppointmentTypeId": item.AppointmentTypeId,
            "allUserList": $scope.allUserList || [],
            "AllBranchesList": $scope.AppListdoctoraddress || [],
        };

        $scope.patientcheckinoutpopupinstance = $uibModal.open({
            "templateUrl": "templates/uibpopups/checkInCheckOutPopup.html",
            "backdrop": "static",
            "scope": $scope,
            "keyboard": false,
            "windowClass": "modal__ninety--",
            "resolve": {
                "obj": function () {
                    return resolveobj;
                }
            },
            "controller": "UsPatientCheckinheckoutCtrl"
        });
        $scope.patientcheckinoutpopupinstance.result.then(function (resp) {
            console.log(resp);
            if (resp.CloseandOpenFlag) {
                if ($scope.AscAppointmentsList.length > 0) {
                    let row = $filter('filter')($scope.AscAppointmentsList, { 'AppointmentID': resp.AppointmentID }, true)[0] || {};
                    let index = $scope.AscAppointmentsList.indexOf(row);
                    $scope.CheckoutRollBack(row, index);
                } else {
                    $scope.CheckoutRollBack();
                };
            };
        }, function (cancel) {
        });
    }


