    $scope.faceLiftPopup = function () {

        if ($scope.UserAccessRights.AllAccessRights.FaceSheetAccess == false) {
            alertify.error("No access for this user.");
            return false;
        }
        //if ($scope.cacheStorageItem.AdmissionId === 0) {
        //    alertify.error("Please Admit the Patient");
        //    return false;
        //}
        if ($scope.selectedApptObj.AppointmentStatusId === 7 || $scope.selectedApptObj.AppointmentStatusId === 5 || $scope.selectedApptObj.AppointmentStatusId === 6) {
            alertify.error("Appointment Cancelled!");
            return;
        }

        if ($scope.selectedApptObj.AppointmentStatusId === 8 || $scope.selectedApptObj.AppointmentStatusId === 9 || $scope.selectedApptObj.AppointmentStatusId === 10) {
            alertify.error("Appointment Rescheduled!");
            return;
        }
        var type = 1;
        var screentype = "ASC";
        //$scope.ActionArea = 'FaceSheet Screen From ASC list screen';
        //$scope.AddAscActionLog();
        let LogItem = {
            "SubModuleId": 20,
            "SubModuleName": "Face sheet",
            "ScreenType": "ASC List",
            "ActionType": "Accessed",
            "OldActionDescription": "",
            "NewActionDescription": "Face sheet Screen from ASC List",
            // "ActionDescription": `Face sheet Screen from ASC List For Appointment ID : ${$scope.LogObj.AppointmentId}`,
        }
        $scope.AddAuditLog(LogItem);
        $scope.AddPatietnDetailsLog($scope.mainobj.PatientId);
        $scope.mInstanceAdd = $uibModal.open({
            "templateUrl": "templates/uibpopups/faceLiftPopup.html",
            "controller": "USFaceSheetPopupCtrl",
            "backdrop": "static",
            "keyboard": false,
            "windowClass": "modal__popup--1 bottom-to-top-modal",
            "resolve": {
                "allUserList": function () { return $scope.allUserList; },
                "SubTab": function () { return type; },
                "ScreenType": function () { return screentype; },
                "ParentObj": function () { return $scope.ParentObj; },
            }
        });
        $scope.mInstanceAdd.result.then(function (resp) {
            GetOTQuickAccessDetails();
            let tabId = $scope.ASCDynamicStatusTabs.Subtab;
            if ([1, 2, 3, 4].includes(tabId)) {
                $scope.SearchSurgeryList(tabId - 1, 'tab');
            } else {
                let roomTypeId = $scope.RoomTypeId || 0;
                $scope.GetApptListByRoomType(roomTypeId, tabId);
            }
        }, function () {
        });
    };


