    $scope.navtoPrintAllAppointments = function (TabVal, str) {
        var subList = "";
        for (var i in $scope.allSubSpecializationsArray) {
            if ($scope.allSubSpecializationsArray[i].isChecked) {
                subList += "," + $scope.allSubSpecializationsArray[i].SubSpecializationId;
            }
        }
        if (subList.charAt(0) === ",") {
            subList = subList.slice(1);
        }
        var consultdate = $filter("date")($scope.SearchObj.ConsultationDt, "yyyy-MM-dd");
        var params = "";

        if (doctorInfo.doctordata.UserAddress[0].UserBranchId === 0) {
            params = {
                "HospitalID": $scope.HospitalId,
                "FromDate": consultdate,
                "ToDate": consultdate,
                "PageSize": $scope.Pagination.Patientitemsperpage,
                "PageNumber": $scope.Pagination.currentPagePatient,
                "SearchText": $scope.SearchObj.searchPatientTxt ? $scope.SearchObj.searchPatientTxt : "",
                "SearchPatientId": $scope.SearchObj.searchPatientIdTxt ? $scope.SearchObj.searchPatientIdTxt : "",
                "RoleId": $scope.userLoginDetails.RoleID,
                "SortType": $scope.SearchObj.SortType,
                "SortBy": $scope.SearchObj.SortBy,
                "SpecializationId": $scope.SpecializationId,
                "SubSpecializationIds": subList,
                "UserId": eHnoteMasterDataService.getLoginId(),
                "PatientId": $scope.SearchObj.PatientId || 0

            };
        }
        else {
            params = {
                "UserBranchId": doctorInfo.doctordata.UserAddress[0].UserBranchId,
                "DoctorID": $scope.cacheStorageItem.DoctorID,
                "FromDate": consultdate,
                "ToDate": consultdate,
                "HospitalID": $scope.HospitalId,
                "PageSize": $scope.Pagination.Patientitemsperpage,
                "PageNumber": $scope.Pagination.currentPagePatient,
                "SearchText": $scope.SearchObj.searchPatientTxt ? $scope.SearchObj.searchPatientTxt : "",
                "SearchPatientId": $scope.SearchObj.searchPatientIdTxt ? $scope.SearchObj.searchPatientIdTxt : "",
                "RoleId": $scope.userLoginDetails.RoleID,
                "SortType": $scope.SearchObj.SortType,
                "SortBy": $scope.SearchObj.SortBy,
                "SpecializationId": $scope.SpecializationId,
                "SubSpecializationIds": subList,
                "UserId": eHnoteMasterDataService.getLoginId(),
                "PatientId": $scope.SearchObj.PatientId || 0
            };
        }

        var newlist1 = "";
        for (var i in $scope.AppointmentStatusFilterArray) {
            if ($scope.AppointmentStatusFilterArray[i].isChecked) {
                if ($scope.AppointmentStatusFilterArray[i].Id != "C") {
                    newlist1 += "," + $scope.AppointmentStatusFilterArray[i].Id;
                }
            }
        }
        if (newlist1.charAt(0) === ",") {
            newlist1 = newlist1.slice(1);
        }

        var newlist2 = "";
        for (var i in $scope.AppointmentVisitFilterArray) {
            if ($scope.AppointmentVisitFilterArray[i].isChecked) {
                newlist2 += "," + $scope.AppointmentVisitFilterArray[i].Id;
            }
        }
        if (newlist2.charAt(0) === ",") {
            newlist2 = newlist2.slice(1);
        }
        var newlist4 = "";
        for (var i in $scope.CheckInFilterArray) {
            if ($scope.CheckInFilterArray[i].isChecked) {
                newlist4 += "," + $scope.CheckInFilterArray[i].Id;
            }
        }
        if (newlist4.charAt(0) === ",") {
            newlist4 = newlist4.slice(1);
        }
        var newlist5 = "";
        for (var i in $scope.Visitreasons) {
            if ($scope.Visitreasons[i].isChecked) {
                newlist5 += "," + $scope.Visitreasons[i].ParentAppointmentVisitReasonId;
                //newlist5 += "," + $scope.Visitreasons[i].ReasonId;
            }
        }
        if (newlist5.charAt(0) === ",") {
            newlist5 = newlist5.slice(1);
        }


        var newlist6 = "";
        for (var i in $scope.MultiselectDoctorlist) {
            if ($scope.MultiselectDoctorlist[i].isChecked) {
                newlist6 += "," + $scope.MultiselectDoctorlist[i].DoctorID;
            }
        }
        if (newlist6.charAt(0) === ",") {
            newlist6 = newlist6.slice(1);
        }

        var newlist7 = "";
        for (var i in $scope.BookingTypesArray) {
            if ($scope.BookingTypesArray[i].IsChecked) {
                newlist7 += "," + $scope.BookingTypesArray[i].BookingTypeId;
            }
        }
        if (newlist7.charAt(0) === ",") {
            newlist7 = newlist7.slice(1);
        }

        var newlist10 = "";
        for (var i in $scope.AppointmentStatusArray) {
            if ($scope.AppointmentStatusArray[i].IsChecked) {
                newlist10 += "," + $scope.AppointmentStatusArray[i].AppointmentStatusId;
            }
        }
        if (newlist10.charAt(0) === ",") {
            newlist10 = newlist10.slice(1);
        }

        var newlist11 = "";
        for (var i in $scope.BookedstatusFilterList) {
            if ($scope.BookedstatusFilterList[i].IsChecked) {
                newlist11 += "," + $scope.BookedstatusFilterList[i].Id;
            }
        }
        if (newlist11.charAt(0) === ",") {
            newlist11 = newlist11.slice(1);
        }
        var newlist8 = "";
        for (var i in $scope.ProfileStatusList) {
            if ($scope.ProfileStatusList[i].IsChecked) {
                newlist8 += "," + $scope.ProfileStatusList[i].Id;
            }
        }
        if (newlist8.charAt(0) === ",") {
            newlist8 = newlist8.slice(1);
        }

        var newlist9 = "";
        for (var i in $scope.PatientTagList) {
            if ($scope.PatientTagList[i].IsChecked) {
                newlist9 += "," + $scope.PatientTagList[i].HospitalEquipmentId;
            }
        }
        if (newlist9.charAt(0) === ",") {
            newlist9 = newlist9.slice(1);
        }

        var Locationids = '';
        if ($scope.GetAllIndicatorForFacility == 1 || $scope.AppListselectedclinic.ClinicId === 0) {
            var TempAppListdoctoraddress = $filter("filter")($scope.AppListdoctoraddress, function (iterator, ind) { return iterator.ClinicId !== 0; });
            Locationids = _.pluck(TempAppListdoctoraddress, "ClinicId").join(",");
        } else {
            Locationids = $scope.AppListselectedclinic.ClinicId;
        }

        let surgeryCategoryIds = $scope.GetASCListSurgeryCategoryIds();
        let appointmentTypeStatusId = getASCModuleAppointmentTypeId();

        params.AppointmentStatusIDLst = newlist1;
        params.VisitStatusIDLst = newlist2;
        params.AppointmentTypeStatusIDList = appointmentTypeStatusId;
        params.CheckInStatusIDList = newlist4;
        params.VisitReasonIdList = newlist5;
        params.DoctorIds = newlist6;
        params.BookingTypeIds = angular.copy(newlist7);
        params.AppointmentStatusIds = angular.copy(newlist10);
        params.BookingStatusIds = angular.copy(newlist11);
        params.ProfileStatusIds = angular.copy(newlist8);
        params.PatientTagListIds = angular.copy(newlist9);
        params.Locationids = angular.copy(Locationids);
        params.SurgeryCategoryIds = angular.copy(surgeryCategoryIds);

        var CreatedByName = "";
        if (doctorInfo.doctordata.User.length > 0) {
            CreatedByName = doctorInfo.doctordata.User[0].SecondUserFullName || "";
        }

        eHnoteMainAppointmentService.OPAppointmentListPrintDetails(params).then(function (resp) {
            console.log("B");
            if (resp.data.AppointmentList.length > 0) {
                $scope.OPAppointmentListPrintData = [];

                $scope.OPApptList = _.uniq(resp.data.AppointmentList, false, function (p) { return p.DoctorID; });
                angular.forEach($scope.OPApptList, function (Aitem) {
                    $scope.filterOPApptList = [];
                    $scope.filterOPApptList = $filter("filter")(resp.data.AppointmentList, function (kitem, index) { return kitem.DoctorID == Aitem.DoctorID });
                    if ($scope.filterOPApptList.length > 0) {
                        $scope.IndividualDrAppt = [];
                        var obj = {
                            "DoctorID": $scope.filterOPApptList[0].DoctorID,
                            "DoctorName": $scope.filterOPApptList[0].SecondUserFullName || "",
                            "DoctorAppts": $scope.filterOPApptList || [],
                            "UserCount": $scope.filterOPApptList.length || 0,
                        }
                        $scope.OPAppointmentListPrintData.push(obj);
                    }
                });

                var AppointmentListCount = resp.data.count || "";
                var printobj = {
                    "PatientAppointmentDetails": $scope.OPAppointmentListPrintData || [],
                    "AppointmentListCount": AppointmentListCount,
                    "CreatedBy": CreatedByName || ""
                }
                if (TabVal == 1) {
                    USPrintService.generatePatientDetailsPrintusWithOutNotes(printobj, $scope.MultiselectDoctorlist);
                } else {
                    USPrintService.generatePatientDetailsPrintus(printobj, $scope.MultiselectDoctorlist);
                }
            }
        });
        $scope.AddUpdatePrint(str);
    }

