                        if (item.AppointmentID === apptId) {
                            let updatedItem = {
                                ...item,
                                SystemicHistory: $scope.SystemicHistory || [],
                            };
                            updatedItem.hasDiabetes = updatedItem.SystemicHistory.some(inItem =>
                                diabetesIds.includes(inItem.HistoryId)
                            );
                            updatedItem.diabetesString = $scope.diabetesString;
                            return updatedItem;
                        }
                        return item;
