    /* Signing off inside the LASIK / Laser template changes that chart's phase
       statuses, and the Pre / Intra / Post dots on this list are drawn from them.
       The list is not told anything by the popup, so it is re-read once the popup
       closes - the same call the screen makes for itself, with the appointment it
       was on so the selection is kept. Runs whether the popup was closed or
       dismissed, since a sign-off is saved either way. */
    $scope.RefreshAscListAfterLasikTemplate = function (modalInstance) {
        if (!modalInstance || !modalInstance.result) { return; }

        var reload = function () {
            $scope.GetAllAscAppointmentsList($scope.selectedApptObj.AppointmentID || 0);
        };

        modalInstance.result.then(reload, reload);
    };

