                    var checkedArray = _.where($scope.ASCdrCalenderList, { isChecked: true });
                    $scope.AllDoctorsObj.AllDoctorCheck = checkedArray.length > 0 && $scope.ASCdrCalenderList.length === checkedArray.length ? true : false;
