    $scope.StartTimer = "00:00";
    $scope.ItemScope = "";
    $scope.StartDilation = function () {
        var StartTime = $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss");
        var parms = {
            "AppointmentID": $scope.mainobj.AppointmentId,
            "UserId": $scope.UserId,
            "HospitalId": $scope.HospitalId,
            "StartTimer": StartTime,
        };

        eHnoteSurgeryService.AddUpdateDischargeSignOffTimer(parms).then(function (resp) {
            if (resp.data.Status === "Success") {
                $scope.ItemScope = $interval(function () { $scope.callAtInterval(parms.StartTimer); }, 1000);
            }
        }, function () {

        });
    };

    $scope.callAtInterval = function (StartTimer) {
        StartTimer = StartTimer || '';
        if (StartTimer !== '') {
            var now = $filter("date")(new Date(), "dd/MM/yyyy HH:mm:ss");
            var then = $filter("date")(new Date(StartTimer), "dd/MM/yyyy HH:mm:ss");
            var ms = moment(now, "DD/MM/YYYY HH:mm:ss").diff(moment(then, "DD/MM/YYYY HH:mm:ss"));
            var d = moment.duration(ms);
            var h = d.hours();
            var m = d.minutes();
            var sec = d.seconds();
            $scope.StartTimer = m + ":" + sec;
            if (h > 0) {
                $interval.cancel($scope.ItemScope);
                $scope.StartTimer = "45:00";
            }
        }
    };

